// Even more starter foods: world dishes, home cooking, cuts and seafood, baking,
// snacks, drinks and chain restaurant items. Per 100 g, approximate (USDA FoodData
// Central for whole foods; typical recipes for dishes; chains' published numbers
// for restaurant items, which change). Same shape as foods.js; joined onto FOODS there.

const F = (id, name, icon, cat, servings, n) => ({ id, name, icon, cat, servings: servings.map(([label, g]) => ({ label, g })), n });

/** A restaurant item, given as the chain lists it (one item of `g` grams); stored per 100 g. */
const R = (id, name, icon, label, g, item) => ({
  id, name, icon, cat: 'Restaurants',
  servings: [{ label: `1 ${label}`, g }],
  n: Object.fromEntries(Object.entries(item).map(([k, v]) => [k, Math.round((v * 1000) / g) / 10])),
});

